import { useState } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Marquee from './components/Marquee';
import Services from './components/Services';
import WhyUs from './components/WhyUs';
import DoctorProfile from './components/DoctorProfile';
import SmileGallery from './components/SmileGallery';
import Testimonials from './components/Testimonials';
import Appointment from './components/Appointment';
import Footer from './components/Footer';
import FloatingElements from './components/FloatingElements';

function App() {
  return (
    <div className="bg-cream min-h-screen font-body text-navy overflow-hidden">
      <Navbar />
      <main>
        <Hero />
        <Marquee />
        <Services />
        <WhyUs />
        <DoctorProfile />
        <SmileGallery />
        <Testimonials />
        <Appointment />
      </main>
      <Footer />
      <FloatingElements />
    </div>
  );
}

export default App;

import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { useState } from 'react';

// A helper for the custom SVG teeth mockups
const MockupTooth = ({ isBefore }) => {
  return (
    <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-md pb-4 pt-4 px-4 overflow-visible">
      {/* Gums */}
      <path d="M10 30 C 30 50, 70 50, 90 30 C 95 20, 100 0, 100 0 L 0 0 C 0 0, 5 20, 10 30 Z" fill={isBefore ? "#d48b94" : "#e8a4ad"} />

      {/* Teeth */}
      {isBefore ? (
        // Before version: slightly crooked, yellow tint
        <>
          <path d="M30 35 C 30 65, 45 75, 50 75 C 55 75, 50 65, 50 35" fill="#f4e7c3" stroke="#d48b94" strokeWidth="1" />
          <path d="M50 35 C 52 65, 55 70, 65 72 C 70 73, 72 65, 75 35" fill="#e8d8aa" stroke="#d48b94" strokeWidth="1" />
          <path d="M75 30 C 80 50, 85 55, 90 55 C 92 55, 92 40, 95 30" fill="#eeddb1" stroke="#d48b94" strokeWidth="1" />
          <path d="M10 25 C 12 40, 15 45, 20 45 C 25 45, 28 40, 30 30" fill="#eeddb1" stroke="#d48b94" strokeWidth="1" />
        </>
      ) : (
        // After version: straight, bright white
        <>
           <path d="M30 35 C 30 75, 45 80, 50 80 C 55 80, 50 75, 50 35" fill="#ffffff" stroke="#e8a4ad" strokeWidth="0.5" />
           <path d="M50 35 C 50 75, 55 80, 70 80 C 75 80, 75 75, 75 35" fill="#ffffff" stroke="#e8a4ad" strokeWidth="0.5" />
           <path d="M75 30 C 75 55, 80 60, 90 60 C 92 60, 95 50, 95 30" fill="#fcfcfc" stroke="#e8a4ad" strokeWidth="0.5" />
           <path d="M10 25 C 10 45, 15 50, 25 50 C 28 50, 30 45, 30 30" fill="#fcfcfc" stroke="#e8a4ad" strokeWidth="0.5" />
        </>
      )}
    </svg>
  );
};

const BeforeAfterCard = ({ label, delay }) => {
  const [ref, inView] = useInView({ triggerOnce: true, threshold: 0.1 });

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 30 }}
      animate={inView ? { opacity: 1, y: 0 } : { opacity: 0, y: 30 }}
      transition={{ duration: 0.6, delay }}
      className="group"
    >
      <div 
        className="relative w-full aspect-[4/3] rounded-sm overflow-hidden bg-cream cursor-ew-resize border border-navy/5 shadow-md"
      >
        {/* BEFORE image (background layer) */}
        <div className="absolute inset-0 bg-[#f0eadd] flex flex-col items-center justify-center pt-8">
          <div className="w-[80%] opacity-80 mix-blend-multiply">
            <MockupTooth isBefore={true} />
          </div>
          <span className="absolute bottom-4 left-4 text-xs font-semibold uppercase tracking-widest text-navy/40">Before</span>
        </div>

        {/* AFTER image (foreground layer via clip-path) */}
        <div className="absolute inset-0 bg-white flex flex-col items-center justify-center pt-8 transition-all duration-700 ease-in-out [clip-path:polygon(50%_0%,100%_0%,100%_100%,50%_100%)] group-hover:[clip-path:polygon(0%_0%,100%_0%,100%_100%,0%_100%)]">
          <div className="w-[80%]">
            <MockupTooth isBefore={false} />
          </div>
          <span className="absolute bottom-4 right-4 text-xs font-semibold uppercase tracking-widest text-gold drop-shadow-sm">After</span>
        </div>

        {/* Slider Handle (visual only) */}
        <div className="absolute top-0 bottom-0 left-[50%] w-0.5 bg-gold/50 group-hover:bg-gold transition-colors duration-500 z-10 -ml-[1px] group-hover:opacity-0 pointer-events-none">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-white border border-gold/30 shadow-md flex items-center justify-center group-hover:scale-0 transition-transform duration-300">
            <div className="w-4 h-4 text-gold flex justify-between items-center opacity-70">
              <span className="text-[10px]">ΓùÇ</span>
              <span className="text-[10px]">Γû╢</span>
            </div>
          </div>
        </div>
      </div>
      <p className="mt-4 text-center font-heading text-lg text-navy">{label}</p>
    </motion.div>
  );
};

export default function SmileGallery() {
  return (
    <section id="gallery" className="bg-white py-24 px-6 md:px-12 relative">
      <div className="container mx-auto max-w-6xl">
        <div className="text-center mb-16">
          <motion.h2 
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="text-4xl md:text-5xl font-heading text-navy"
          >
            Real Results, <span className="text-gold italic">Real Smiles</span>
          </motion.h2>
          <motion.p
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 0.2 }}
            className="mt-4 text-navy/60 font-light max-w-xl mx-auto"
          >
            Hover over the images to reveal the stunning transformations achieved by our expert specialists.
          </motion.p>
        </div>

        <div className="grid md:grid-cols-3 gap-8 md:gap-12">
          <BeforeAfterCard label="Smile Makeover ┬╖ 3 months" delay={0.1} />
          <BeforeAfterCard label="Whitening ┬╖ 1 session" delay={0.3} />
          <BeforeAfterCard label="Dental Implants ┬╖ 6 months" delay={0.5} />
        </div>
      </div>
    </section>
  );
}
